	conf := inmemConfig(t)
	conf.TrailingLogs = 0
	c := MakeCluster(2, t, conf)
	defer c.Close()

	leader := c.Leader()
	if err := leader.Apply([]byte("a"), conf.HeartbeatTimeout).Error(); err != nil {
		t.Fatalf("apply a: %v", err)
